//! `compileClaudeModelSelection` from the T3 server, over its bundled Claude model catalog.
//!
//! `model_catalog.json` is generated by `tools/gen-catalog` with T3's own function: per model,
//! the result for each effort choice and each boolean option. It is parsed per call and
//! dropped, so it holds no memory between turns.

use serde_json::{Map, Value};

const CATALOG: &str = include_str!("model_catalog.json");
/// `CLAUDE_EFFORT_LEVELS`.
const EFFORT_LEVELS: &[&str] = &["low", "medium", "high", "xhigh", "max"];
/// Boolean option id → settings key.
const FLAGS: &[(&str, &str)] = &[
    ("thinking", "alwaysThinkingEnabled"),
    ("fastMode", "fastMode"),
    ("ultracode", "ultracode"),
];

/// `CompiledClaudeModelSelection`.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Compiled {
    pub api_model_id: String,
    pub effort: Option<String>,
    /// `ultrathink` when the prompt gets T3's `Ultrathink:` prefix.
    pub prompt_effort: Option<String>,
    pub settings: Map<String, Value>,
}

/// The models the T3 server offers clients (`ServerProvider.models`): every model of its
/// bundled catalog, with names, aliases, the legacy flag and option descriptors.
pub fn provider_models() -> Vec<Value> {
    let catalog: Value = serde_json::from_str(CATALOG).unwrap_or(Value::Null);
    match catalog.get("providerModels") {
        Some(Value::Array(models)) => models.clone(),
        _ => Vec::new(),
    }
}

/// Compiles a contract `ModelSelection` (as JSON).
pub fn compile(selection: &Value) -> Compiled {
    let model = selection["model"].as_str().unwrap_or("default").trim();
    let options = selection["options"].as_array().cloned().unwrap_or_default();
    let option = |id: &str| options.iter().find(|o| o["id"] == id).map(|o| &o["value"]);
    let raw_effort = option("effort").and_then(Value::as_str).map(str::trim);
    let catalog: Value = serde_json::from_str(CATALOG).unwrap_or(Value::Null);
    let entry = catalog["models"].as_array().and_then(|models| {
        models.iter().find(|m| m["slug"] == model).or_else(|| {
            models.iter().find(|m| {
                m["aliases"].as_array().is_some_and(|aliases| {
                    aliases
                        .iter()
                        .filter_map(Value::as_str)
                        .any(|a| a.eq_ignore_ascii_case(model))
                })
            })
        })
    });
    let Some(entry) = entry else {
        // Outside the catalog: a known effort level passes, no option descriptors apply.
        return Compiled {
            api_model_id: model.to_string(),
            effort: raw_effort
                .filter(|e| EFFORT_LEVELS.contains(e))
                .map(str::to_string),
            prompt_effort: None,
            settings: Map::new(),
        };
    };
    let base = raw_effort
        .and_then(|e| entry["efforts"].get(e))
        .unwrap_or(&entry["efforts"][""]);
    let mut settings = base["settings"].as_object().cloned().unwrap_or_default();
    let booleans = entry["booleans"].as_array().cloned().unwrap_or_default();
    for (id, key) in FLAGS {
        if !booleans.iter().any(|b| b == id) {
            continue;
        }
        if let Some(flag) = option(id).and_then(Value::as_bool) {
            let compiled = &entry["flags"][format!("{id}={flag}")]["settings"];
            match compiled.get(*key) {
                Some(value) => settings.insert((*key).to_string(), value.clone()),
                None => settings.remove(*key),
            };
        }
    }
    // T3's order: alwaysThinkingEnabled, fastMode, ultracode (ordered.rs keeps it on the wire).
    Compiled {
        api_model_id: base["apiModelId"].as_str().unwrap_or(model).to_string(),
        effort: base["effort"].as_str().map(str::to_string),
        prompt_effort: base["promptEffort"].as_str().map(str::to_string),
        settings,
    }
}

/// `applyClaudePromptEffortPrefix`: trims the text, and prefixes `Ultrathink:` for the
/// `ultrathink` effort unless the text is a slash command or already has it.
pub fn prompt_text(text: &str, prompt_effort: Option<&str>) -> String {
    let trimmed = text.trim();
    if trimmed.is_empty() || prompt_effort != Some("ultrathink") || is_slash_command(trimmed) {
        return trimmed.to_string();
    }
    if trimmed.starts_with("Ultrathink:") {
        return trimmed.to_string();
    }
    format!("Ultrathink:\n{trimmed}")
}

/// `/^\/[^\s/]+(?:\s|$)/u`.
fn is_slash_command(text: &str) -> bool {
    let Some(rest) = text.strip_prefix('/') else {
        return false;
    };
    let name_len = rest
        .find(|c: char| c.is_whitespace() || c == '/')
        .unwrap_or(rest.len());
    name_len > 0
        && rest
            .get(name_len..)
            .and_then(|tail| tail.chars().next())
            .is_none_or(char::is_whitespace)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn selection(model: &str, options: Value) -> Value {
        json!({"instanceId": "claudeAgent", "model": model, "options": options})
    }

    #[test]
    fn compiles_like_t3() {
        let haiku = compile(&selection("claude-haiku-5-5", json!([])));
        assert_eq!(haiku.api_model_id, "claude-haiku-5-5");
        assert_eq!(haiku.effort.as_deref(), Some("medium"));
        assert!(haiku.settings.is_empty());
        let opus = compile(&selection(
            "opus",
            json!([{"id": "effort", "value": "ultrathink"}]),
        ));
        assert_eq!(opus.api_model_id, "claude-opus-5-5");
        assert_eq!(opus.prompt_effort.as_deref(), Some("ultrathink"));
        assert_eq!(opus.settings["fastMode"], json!(false));
        let fast = compile(&selection(
            "claude-opus-5-5",
            json!([{"id": "fastMode", "value": true}]),
        ));
        assert_eq!(fast.settings["fastMode"], json!(true));
        let custom = compile(&selection(
            "my-model",
            json!([{"id": "effort", "value": "high"}]),
        ));
        assert_eq!(custom.api_model_id, "my-model");
        assert_eq!(custom.effort.as_deref(), Some("high"));
    }

    #[test]
    fn prompt_text_follows_apply_claude_prompt_effort_prefix() {
        assert_eq!(prompt_text("  hi \n", None), "hi");
        assert_eq!(prompt_text("hi", Some("ultrathink")), "Ultrathink:\nhi");
        assert_eq!(
            prompt_text("/review now", Some("ultrathink")),
            "/review now"
        );
        assert_eq!(prompt_text("/a/b", Some("ultrathink")), "Ultrathink:\n/a/b");
        assert_eq!(
            prompt_text("Ultrathink: x", Some("ultrathink")),
            "Ultrathink: x"
        );
    }
}
